import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"59. 了解目标文件","description":"The Little Book of C 中文版 — 59. 了解目标文件","frontmatter":{"title":"59. 了解目标文件","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 59. 了解目标文件","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":59,"sidebarWeight":59,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/059-Understanding the Object File","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/059-Understanding the Object File"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/059-Understanding the Object File.md","filePath":"posts/c教程/zh-CN/06-编译与构建/059-Understanding the Object File.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/06-编译与构建/059-Understanding the Object File.md"};function i(d,a,l,o,c,h){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/059-Understanding the Object File)</p><p>到现在为止，你已经看到了<code>.o</code>文件出现在每个构建步骤中，即源代码和可执行文件之间的中间产品。但它们里面到底是什么？</p><p>目标文件是编译器打包机器代码、符号表和元数据的方式，可供链接器组装成最终程序。了解目标文件可以帮助您调试链接错误、检查性能，甚至对编译的代码进行逆向工程。</p><h4 id="步骤-1-生命周期回顾" tabindex="-1">步骤 1. 生命周期回顾 <a class="header-anchor" href="#步骤-1-生命周期回顾" aria-label="Permalink to &quot;步骤 1. 生命周期回顾&quot;">​</a></h4><p>编译管道如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source.c ──&gt; preprocessor ──&gt; compiler ──&gt; assembler ──&gt; linker</span></span>
<span class="line"><span>     |                           |             |          |</span></span>
<span class="line"><span>     |                        hello.s        hello.o     a.out</span></span></code></pre></div><p>你的<code>.c</code>文件变成<code>.o</code>文件在汇编之后、链接之前。</p><p>每个<code>.o</code>是独立的，它知道它定义了什么，它需要什么，以及它的代码位于内存中的位置。</p><h4 id="步骤-2-目标文件格式" tabindex="-1">步骤 2. 目标文件格式 <a class="header-anchor" href="#步骤-2-目标文件格式" aria-label="Permalink to &quot;步骤 2. 目标文件格式&quot;">​</a></h4><p>不同的操作系统使用不同的二进制格式：</p><table tabindex="0"><thead><tr><th>操作系统</th><th>格式</th><th>典型扩展</th></tr></thead><tbody><tr><td>Linux</td><td>ELF（可执行和可链接格式）</td><td><code>.o</code>,<code>.so</code>, 可执行</td></tr><tr><td>macOS</td><td>马赫-O</td><td><code>.o</code>,<code>.dylib</code></td></tr><tr><td>窗户</td><td>咖啡/PE</td><td><code>.obj</code>,<code>.dll</code>,<code>.exe</code></td></tr></tbody></table><p>在 Linux 上，ELF 占主导地位，因此我们将使用它作为参考。</p><h4 id="步骤-3-目标文件内的部分" tabindex="-1">步骤 3. 目标文件内的部分 <a class="header-anchor" href="#步骤-3-目标文件内的部分" aria-label="Permalink to &quot;步骤 3. 目标文件内的部分&quot;">​</a></h4><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c -o main.o</span></span>
<span class="line"><span>readelf -S main.o</span></span></code></pre></div><p>你会看到如下输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ 1] .text     PROGBITS  code and functions</span></span>
<span class="line"><span>[ 2] .data     PROGBITS  initialized global variables</span></span>
<span class="line"><span>[ 3] .bss      NOBITS    uninitialized globals</span></span>
<span class="line"><span>[ 4] .rodata   PROGBITS  constants (e.g., string literals)</span></span>
<span class="line"><span>[ 5] .symtab   SYMTAB    symbol table</span></span>
<span class="line"><span>[ 6] .strtab   STRTAB    string table</span></span>
<span class="line"><span>[ 7] .rel.text RELA      relocation info</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部分</th><th>内容</th></tr></thead><tbody><tr><td><code>.text</code></td><td>编译后的机器代码（函数）</td></tr><tr><td><code>.data</code></td><td>具有初始值的全局变量</td></tr><tr><td><code>.bss</code></td><td>没有初始值的全局变量</td></tr><tr><td><code>.rodata</code></td><td>常数，<code>const</code>变量、字符串文字</td></tr><tr><td><code>.symtab</code></td><td>符号表：函数和变量元数据</td></tr><tr><td><code>.rel*</code></td><td>搬迁信息，如何将此文件连接到其他文件</td></tr></tbody></table><h4 id="步骤-4-检查符号" tabindex="-1">步骤 4. 检查符号 <a class="header-anchor" href="#步骤-4-检查符号" aria-label="Permalink to &quot;步骤 4. 检查符号&quot;">​</a></h4><p>每一个<code>.o</code>文件包含描述其功能和变量的符号。列出它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm main.o</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000000000000000 T main</span></span>
<span class="line"><span>                 U printf</span></span></code></pre></div><table tabindex="0"><thead><tr><th>符号</th><th>意义</th></tr></thead><tbody><tr><td><code>T</code></td><td>定义在文本（代码）部分</td></tr><tr><td><code>U</code></td><td>未定义，必须由另一个文件或库提供</td></tr><tr><td><code>D</code></td><td>定义在数据部分</td></tr><tr><td><code>B</code></td><td>定义在 bss 部分</td></tr><tr><td><code>R</code></td><td>在只读数据中定义</td></tr><tr><td><code>W</code></td><td>弱符号（可以被覆盖）</td></tr></tbody></table><p>这里，<code>main</code>被定义，<code>printf</code>未定义，意味着链接器必须在 C 标准库中找到它。</p><h4 id="小代码-检查多文件示例" tabindex="-1">小代码：检查多文件示例 <a class="header-anchor" href="#小代码-检查多文件示例" aria-label="Permalink to &quot;小代码：检查多文件示例&quot;">​</a></h4><p>数学.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int mul(int a, int b) { return a * b; }</span></span></code></pre></div><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int, int);</span></span>
<span class="line"><span>int mul(int, int);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(2, 3) * mul(1, 4));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译但不链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c math.c</span></span></code></pre></div><p>检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm main.o</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U add</span></span>
<span class="line"><span>U mul</span></span>
<span class="line"><span>U printf</span></span>
<span class="line"><span>T main</span></span></code></pre></div><p><code>U</code>表示未定义，链接器必须解决这些问题。</p><p>现在检查<code>math.o</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T add</span></span>
<span class="line"><span>T mul</span></span></code></pre></div><p>这些定义将满足链接器的要求。</p><p>链接并检查结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o -o app</span></span>
<span class="line"><span>nm app | grep add</span></span></code></pre></div><p>现在你会看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000000000401136 T add</span></span></code></pre></div><p>链接器重新定位<code>add()</code>进入其最终地址。</p><h4 id="步骤-5-符号可见性" tabindex="-1">步骤 5. 符号可见性 <a class="header-anchor" href="#步骤-5-符号可见性" aria-label="Permalink to &quot;步骤 5. 符号可见性&quot;">​</a></h4><p>默认情况下，每个函数和全局变量都有外部链接，对链接器可见。</p><p>使用<code>static</code>限制当前文件的可见性：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static int hidden_func(void) { return 42; }</span></span></code></pre></div><p>现在<code>nm</code>不会将其列为导出符号。这可以保持您的二进制文件干净并防止文件之间的名称冲突。</p><h4 id="步骤-6-检查搬迁" tabindex="-1">步骤 6. 检查搬迁 <a class="header-anchor" href="#步骤-6-检查搬迁" aria-label="Permalink to &quot;步骤 6. 检查搬迁&quot;">​</a></h4><p>目标文件尚不知道最终地址，因此它们存储重定位条目：链接器稍后必须填充的地址占位符。</p><p>检查它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>readelf -r main.o</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Relocation section &#39;.rela.text&#39;:</span></span>
<span class="line"><span>0000000000000010 R_X86_64_PC32 printf-0x4</span></span></code></pre></div><p>这告诉链接器：</p><p>“链接时，将此占位符替换为<code>printf()</code>.”</p><h4 id="步骤-7-反汇编代码" tabindex="-1">步骤 7. 反汇编代码 <a class="header-anchor" href="#步骤-7-反汇编代码" aria-label="Permalink to &quot;步骤 7. 反汇编代码&quot;">​</a></h4><p>可以看到实际的机器指令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -d main.o</span></span></code></pre></div><p>输出片段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000000000000000 &lt;main&gt;:</span></span>
<span class="line"><span>   0: 55                    push   %rbp</span></span>
<span class="line"><span>   1: 48 89 e5              mov    %rsp,%rbp</span></span>
<span class="line"><span>   4: b8 00 00 00 00        mov    $0x0,%eax</span></span></code></pre></div><p>每条指令对应于已编译的 C 代码。这是验证优化、检查内联或研究生成的程序集的方式。</p><h4 id="步骤-8-混合目标文件" tabindex="-1">步骤 8. 混合目标文件 <a class="header-anchor" href="#步骤-8-混合目标文件" aria-label="Permalink to &quot;步骤 8. 混合目标文件&quot;">​</a></h4><p>因为<code>.o</code>文件包含清晰的符号元数据，您可以混合来自不同语言的目标文件，例如 C 和汇编。</p><p>总和</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.globl sum</span></span>
<span class="line"><span>sum:</span></span>
<span class="line"><span>    addq %rsi, %rdi</span></span>
<span class="line"><span>    movq %rdi, %rax</span></span>
<span class="line"><span>    ret</span></span></code></pre></div><p>编译并链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>as sum.s -o sum.o</span></span>
<span class="line"><span>gcc main.c sum.o -o app</span></span></code></pre></div><p>这就是 C 与低级代码干净地集成的方式。</p><h4 id="步骤-9-对象文件大小和内容" tabindex="-1">步骤 9. 对象文件大小和内容 <a class="header-anchor" href="#步骤-9-对象文件大小和内容" aria-label="Permalink to &quot;步骤 9. 对象文件大小和内容&quot;">​</a></h4><p>检查文件大小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>size main.o</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text    data     bss     dec     hex filename</span></span>
<span class="line"><span>45      4        0       49      31  main.o</span></span></code></pre></div><p>-<code>text</code>→ 代码大小 -<code>data</code>→ 初始化全局变量 -<code>bss</code>→ 未初始化的变量</p><h4 id="步骤-10-小代码-调查一切" tabindex="-1">步骤 10. 小代码：调查一切 <a class="header-anchor" href="#步骤-10-小代码-调查一切" aria-label="Permalink to &quot;步骤 10. 小代码：调查一切&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c hello.c -o hello.o</span></span>
<span class="line"><span>readelf -h hello.o          # ELF header</span></span>
<span class="line"><span>readelf -S hello.o          # Sections</span></span>
<span class="line"><span>readelf -s hello.o | head   # Symbol table</span></span>
<span class="line"><span>readelf -r hello.o          # Relocations</span></span>
<span class="line"><span>objdump -d hello.o | head   # Disassembly</span></span></code></pre></div><p>您将获得有关 C 代码在编译器看来如何的完整低级视图。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>了解目标文件可以帮助您：</p><ul><li>调试链接错误和符号冲突</li><li>检查编译器优化</li><li>将C与汇编集成</li><li>手动构建静态和共享库</li><li>查看二进制文件中的实际内容</li></ul><p>在系统编程中，这种见解将代码用户与代码工程师分开。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>创建两个<code>.o</code>相互依赖的文件并检查其未定义的符号。</li><li>使用<code>readelf -S</code>比较<code>.text</code>,<code>.data</code>， 和<code>.bss</code>对于不同的程序。 3.添加一个全局变量，看看它是如何出现的<code>.data</code>或者<code>.bss</code>.</li><li>将函数标记为<code>static</code>并确认它从以下位置消失<code>nm</code>输出。</li><li>编译<code>-O2</code>并观察拆卸中的变化<code>objdump -d</code>.</li></ol><p>接下来，您将通过从头开始构建自己的基于 Makefile 的编译管道，显式编写每个阶段来完成第 6 章的转换<code>.c</code>文件到<code>.o</code>,<code>.a</code>， 和<code>.so</code>工件就像真正的编译器工具链一样。</p>`,86)])])}const u=s(p,[["render",i]]);export{b as __pageData,u as default};
